        public function addg($ckey)
        {
            $this->company = $this->m_entreprises->get_key($ckey);
            $iduser = $this->input->post('userconnected');
            $idsg = $this->input->post('sousgareconnect');
            $idcp = $this->input->post('compconnected');
            $gare_posd = strpos($this->input->post('itineraireheure'), '.');
            
            $sub_gdp = substr($this->input->post('itineraireheure'), 0, $gare_posd);
            $sub_direction = substr($this->input->post('itineraireheure'), $gare_posd + 1, strlen($this->input->post('itineraireheure')));
            
            $sb = strpos($sub_direction, '.');
            $sub_heure = substr($sub_direction, 0, $sb);

            $suheure = substr($sub_direction, $sb + 1, strlen($sub_direction));
           
            $lg = strpos($sub_heure, '-');
            $gd = substr($sub_heure, 0, $lg);

            
            $today = mdate("%Y-%m-%d", now('UTC'));
            $compter = $this->db->query("SELECT COUNT(code_progr) AS id FROM programme WHERE createdatepr = '$today' AND gareidentif = '$gd'")->row();
            $tp = $this->input->post('tariftype');
            $cts = $this->input->post('categorie');
            $dts = $this->input->post('datedp');

            
            if($gd === 'OUA12')
            {

               $gd4 = 'WUA12';
            }
            else
            {
                $gd4 = $gd;
                                
            }

            $pcd2 = mdate("%y%m%d", now('UTC')).$gd4.($compter->id + 1);
            $pc2 = mdate("%d", now('UTC')).$gd4.($compter->id + 1);
            
            $arrayprog = array(
                'code_progr' => $pcd2,
                'depart_code' => $pc2,
                'id_heur' => $sub_gdp,
                'gareidentif' => $gd,
                'typetarif' => $this->input->post('tariftype'),
                'categori' => $this->input->post('categorie'),
                'intervalle1' => $this->input->post('debut'),
                'intervalle2' => $this->input->post('fin'),
                'dateheure_prog' => $this->input->post('datedp').'-'.$suheure,
                'date_progr' => $this->input->post('datedp'),
                'createdatepr' => mdate("%Y-%m-%d", now('UTC')),
                'createdpg_at' => now('UTC'),
            );

            if($sub_gdp != '' AND $tp != '' AND $cts != '' AND $dts >= '$today'){
                $pr = $this->m_programme->create($arrayprog);
                if ($pr != NULL) {
                    $this->property['INSERT_SUCCESS'] = TRUE;
                }
            }
            redirect('gares/'.$this->session->company->ekey. '/gTv/'.$gd .'/prog/'.$iduser.'/'.$idsg.'/'.mdate("%d/%m/%Y", now('UTC')));
        }

        public function editgare_($ckey, $idpr, $cdb)
        {
            $this->company = $this->m_entreprises->get_key($ckey);
            $iduser = $this->input->post('userconnected');
            $idsg = $this->input->post('sousgareconnect');
            $idcp = $this->input->post('compconnected');
            $post_heure = strpos($this->input->post('heureprog'), '.');
            
            $sub_heure = substr($this->input->post('heureprog'), 0, $post_heure);
            $subheure = substr($this->input->post('heureprog'), $post_heure + 1, strlen($this->input->post('heureprog')));
            
            $sb = strpos($subheure, '.');
            $sub_heu = substr($subheure, 0, $sb);

            $suheure = substr($subheure, $sb + 1, strlen($subheure));
           
            $lg = strpos($sub_heu, '-');
            $gd = substr($sub_heu, 0, $lg);

            $today = mdate("%Y-%m-%d", now('UTC'));

            $tp = $this->input->post('tariftype');
            $cts = $this->input->post('categorie');
            $dts = $this->input->post('dateprogramme');

            $compter = $this->db->query("SELECT COUNT(code_progr) AS id FROM programme WHERE createdatepr = '$today' AND gareidentif = '$gd'")->row();
            
            $cgbselect = $this->input->post('ouotnouveau');
            $cgb = $this->input->post('ouotancien');

            if($sub_heure != '' AND $tp != '' AND $cts != '' AND $dts >= '$today'){
                if($cgbselect == '')
                {
                    $arrayedit = array(
                        'depart_code' => $cdb,
                        'id_heur' => $sub_heure,
                        'gareidentif' => $gd,
                        'typetarif' => $this->input->post('tariftype'),
                        'categori' => $this->input->post('categorie'),
                        'intervalle1' => $this->input->post('debut'),
                        'intervalle2' => $this->input->post('fin'),
                        'dateheure_prog' => $this->input->post('dateprogramme').'-'.$suheure,
                        'date_progr' => $this->input->post('dateprogramme'),
                    );
                    if($this->m_programme->update($idpr, $arrayedit) != FALSE)
                    {
                        
                        $nbp = $this->input->post('fin');
                        $cte = $this->input->post('categorie');
                        $d = $this->input->post('dateprogramme');

                        $this->db->query("UPDATE programme SET categori = '$cte' WHERE depart_code = '$cdb' AND date_progr = '$d'");
                        $this->db->query("UPDATE passager JOIN programme ON passager.code_pro = programme.code_progr SET num_cat = '$cte' WHERE depart_code = '$cdb'");
                        

                        $this->property['UPDATE_SUCCESS'] = TRUE;
                    
                        redirect('gares/'.$this->session->company->ekey. '/gTv/'. $gd. '/prog/'.$iduser.'/'.$idsg.'/'.  mdate("%d/%m/%Y", now('UTC')));
                    }
                }
                if($cgbselect != '')
                {
                    if($cgbselect >= $cgb)
                    {
                        $arrayedit = array(
                            'depart_code' => $cdb,
                            'id_heur' => $sub_heure,
                            'gareidentif' => $gd,
                            'typetarif' => $this->input->post('tariftype'),
                            'categori' => $this->input->post('categorie'),
                            'intervalle1' => $this->input->post('debut'),
                            'intervalle2' => $this->input->post('fin'),
                            'dateheure_prog' => $this->input->post('dateprogramme').'-'.$suheure,
                            'date_progr' => $this->input->post('dateprogramme'),
                        );
                        if($this->m_programme->update($idpr, $arrayedit) != FALSE)
                        {
                            
                            $nbp = $this->input->post('fin');
                            $cte = $this->input->post('categorie');
                            $d = $this->input->post('dateprogramme');
        
                            $this->db->query("UPDATE programme SET categori = '$cte' WHERE depart_code = '$cdb' AND date_progr = '$d'");
                            $this->db->query("UPDATE passager JOIN programme ON passager.code_pro = programme.code_progr SET num_cat = '$cte' WHERE depart_code = '$cdb'");
                            
        
                            $this->property['UPDATE_SUCCESS'] = TRUE;
                        
                            redirect('gares/'.$this->session->company->ekey. '/gTv/'. $gd. '/prog/'.$iduser.'/'.$idsg.'/'.  mdate("%d/%m/%Y", now('UTC')));
        

                        }
                    }
                    else
                    {
                        redirect('gares/'.$this->session->company->ekey. '/gTv/'. $gd. '/prog/'.$iduser.'/'.$idsg.'/'. mdate("%d/%m/%Y", now('UTC')));
        
                    }
                }
            
            }
        }

