        //add sousgareligneposition
        
        public function addligne($ckey, $codeexpgare)
        {
            $this->company = $this->m_entreprises->get_key($ckey);
            $idsg = $this->input->post('sousgareconnect');
            $idcp = $this->input->post('compconnected');
            $iduser = $this->input->post('userconnected');

            $l = $this->input->post('_nomligne');
            $sgr = $this->input->post('_nomsousgare');
            $ps = $this->input->post('position');
            $hrsg = $this->input->post('heureidprog');

            $selct = $this->db->query("SELECT * FROM positionlignegare WHERE positionlignegare.idligne = '$l' AND positionlignegare.idsousgar = '$sgr' AND positionlignegare.idposit = '$ps' AND positionlignegare.lgheures = '$hrsg'")->row();

            $argarray = array(
                'idligne' => $this->input->post('_nomligne'),
                'idsousgar' => $this->input->post('_nomsousgare'),
                'idposit' => $this->input->post('position'),
                'lgheures' => $this->input->post('heureidprog'),
            );
            if ($selct === NULL){

                $this->m_sousgareligne->create($argarray);
            
                $this->property['UPDATE_SUCCESS'] = TRUE;

                redirect('gares/souslignegares/'.$this->session->company->ekey. '/'. $codeexpgare. '/'.$iduser.'/'.$idsg);

            }
            else
            {
                redirect('gares/'.$this->session->company->ekey. '/gTv/'. $codeexpgare. '/prog/'.$iduser.'/'.$idsg.'/'.  mdate("%d/%m/%Y", now('UTC')));
            }
            
        }

        ///modifier
        public function updateligne($ckey, $codeexpgare, $id)
        {
            $this->company = $this->m_entreprises->get_key($ckey);
            $idsg = $this->input->post('sousgareconnect');
            $idcp = $this->input->post('compconnected');
            $iduser = $this->input->post('userconnected');
            $argarray = array(
                'idligne' => $this->input->post('_nomligne'),
                'idsousgar' => $this->input->post('_nomsousgare'),
                'idposit' => $this->input->post('position'),
            );
            
            $upgd = $this->m_sousgareligne->update($id, $argarray);
            if ($upgd != FALSE)
            
                $this->property['UPDATE_SUCCESS'] = TRUE;
            redirect('gares/'.$this->session->company->ekey. '/gTv/'. $codeexpgare. '/prog/'.$iduser.'/'.$idsg.'/'. mdate("%d/%m/%Y", now('UTC')));

        }
        //fidelite

        public function addpassagerfi($ckey)
        {
            if ($this->_sale_nonce_duplicate()) {
                return;
            }

            if ($this->_sale_compte_arret_guard()) {
                return;
            }

            if (!isset($this->m_ordres)) {
                $this->load->model('Ordres_model', 'm_ordres');
            }

            $this->load->library('sale_passager_service', null, 'sale_svc');
            $this->company = $this->m_entreprises->get_key($ckey);
            session_release_lock();
            $today = mdate('%Y-%m-%d', now('UTC'));
            $this->sale_svc->release_expired_reservations($today);
                $gidc = $this->input->post('gareconnect');
                $sgid = $this->input->post('sousgareconnect');
